                            // = forall k', a_to_p(a).satisfied_by(ex.suffix(i).suffix(j).suffix(k'))
                        };
                    };
                };

                // Show eventually(always(tla_forall(a_to_p))).satisfied_by(ex.suffix(i))
                eventually_proved_by_witness(ex.suffix(i), always(tla_forall(a_to_p)), j);
